package com.hrflow.controller; import com.hrflow.entity.*;import com.hrflow.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*; @RestController@RequestMapping("/api/dashboard")@RequiredArgsConstructor public class DashboardController{final EmployeeRepository employees;final LeaveRequestRepository leaves;final AttendanceRepository attendance;final PayrollRepository payroll;final JobRepository jobs;@GetMapping public Map<String,Object> stats(){return Map.of("totalEmployees",employees.count(),"activeEmployees",employees.findAll().stream().filter(e->e.getStatus()==EmploymentStatus.ACTIVE).count(),"onLeave",employees.findAll().stream().filter(e->e.getStatus()==EmploymentStatus.ON_LEAVE).count(),"pendingLeaveRequests",leaves.countByStatus(LeaveStatus.PENDING),"presentToday",attendance.countByAttendanceDate(LocalDate.now()),"openJobPositions",jobs.findByStatus("OPEN").size(),"payrollRecords",payroll.count());}}
